// Extract message dari Telegram webhook
const body = $input.first().json.body || $input.first().json;
const message = body.message || {};
const text = message.text || '';
const chatId = message.chat?.id || '';
const username = message.from?.username || message.from?.first_name || 'User';

// Check if it's a command or SQL
let sql = text;
if (text.startsWith('/docs')) {
  sql = text.replace('/docs', '').trim();
}

// Check if contains CREATE TABLE
const hasSQL = sql.toUpperCase().includes('CREATE TABLE');

return [{
  json: {
    chatId,
    username,
    originalText: text,
    sql,
    hasSQL,
    isStart: text === '/start',
    isHelp: text === '/help'
  }
}];

// Parse SQL dan extract CREATE TABLE statements
const sqlInput = $input.first().json.sql || '';
const chatId = $input.first().json.chatId;
const username = $input.first().json.username;

const tablePattern = /CREATE\s+TABLE\s+(?:IF\s+NOT\s+EXISTS\s+)?(?:public\.)?["']?(\w+)["']?\s*\(([\s\S]*?)\)(?:\s*;)?/gi;

const tables = [];
let match;

while ((match = tablePattern.exec(sqlInput)) !== null) {
  const tableName = match[1];
  const tableBody = match[2];

  const columns = [];
  const lines = tableBody.split(',');

  for (const line of lines) {
    const trimmed = line.trim();
    if (!trimmed) continue;
    if (/^(CONSTRAINT|PRIMARY\s+KEY\(|FOREIGN\s+KEY|UNIQUE\(|CHECK\(|INDEX)/i.test(trimmed)) continue;

    const colMatch = trimmed.match(/^["']?(\w+)["']?\s+(\w+(?:\([^)]+\))?)/i);
    if (colMatch) {
      columns.push({
        name: colMatch[1],
        type: colMatch[2]
      });
    }
  }

  if (columns.length > 0) {
    tables.push({
      name: tableName,
      columns: columns,
      definition: match[0]
    });
  }
}

return [{ json: { tables, chatId, username, tableCount: tables.length } }];

// Generate help/welcome message
const chatId = $input.first().json.chatId;
const isStart = $input.first().json.isStart;
const isHelp = $input.first().json.isHelp;

let message = '';

if (isStart) {
  message = `👋 *Selamat datang di SQL Docs Bot!*

` +
    `Saya bisa generate dokumentasi dari SQL query.

` +
    `*Cara Pakai:*
` +
    `1️⃣ Kirim \`/docs\` + SQL query
` +
    `2️⃣ Atau langsung kirim CREATE TABLE

` +
    `*Contoh:*
` +
    `\`\`\`
/docs CREATE TABLE users (
  id serial,
  name varchar(100)
);
\`\`\`

` +
    `_Powered by n8n + Ollama AI_ 🤖`;
} else if (isHelp) {
  message = `📖 *BANTUAN*

` +
    `*Commands:*
` +
    `/start - Pesan selamat datang
` +
    `/docs - Generate dokumentasi
` +
    `/help - Bantuan ini

` +
    `*Format:*
` +
    `Kirim CREATE TABLE statement, hasil akan dikirim + upload ke Google Drive.`;
} else {
  message = `🤔 Tidak ditemukan CREATE TABLE.

` +
    `Kirim SQL dengan format:
` +
    `\`\`\`sql
CREATE TABLE nama (
  kolom tipe
);
\`\`\`

` +
    `Ketik /help untuk bantuan.`;
}

return [{ json: { chatId, message, isError: true } }];

