// Format hasil untuk Telegram + Drive
const tables = $('Parse SQL Tables').first().json.tables;
const chatId = $('Parse SQL Tables').first().json.chatId;
const username = $('Parse SQL Tables').first().json.username;
const aiResponse = $input.first().json.message?.content || '{}';

// Parse AI response
let aiDoc = { tables: [] };
try {
  const jsonMatch = aiResponse.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    aiDoc = JSON.parse(jsonMatch[0]);
  }
} catch (e) {
  aiDoc = { tables: [] };
}

// Build Telegram message
let telegramMsg = `📚 *DOKUMENTASI DATABASE*\n`;
telegramMsg += `━━━━━━━━━━━━━━━━━━━━━━━\n\n`;

// Build Markdown for Drive
let markdown = `# 📚 Dokumentasi Database Schema\n\n`;
markdown += `> **Generated:** ${new Date().toISOString()}\n`;
markdown += `> **By:** @${username}\n`;
markdown += `> **Total Tables:** ${tables.length}\n\n---\n\n`;

markdown += `## 📋 Daftar Tables\n\n`;
markdown += `| No | Nama Table | Deskripsi |\n`;
markdown += `|----|------------|-----------|\n`;

tables.forEach((table, idx) => {
  const aiTable = aiDoc.tables?.find(t => t.name === table.name) || {};
  const desc = aiTable.description || `Tabel ${table.name}`;

  // Telegram
  telegramMsg += `*${idx + 1}. ${table.name}*\n`;
  telegramMsg += `📝 ${desc}\n\n`;
  telegramMsg += `\`\`\`\n`;

  // Markdown summary
  markdown += `| ${idx + 1} | \`${table.name}\` | ${desc} |\n`;

  table.columns.forEach((col, cidx) => {
    const colDesc = aiTable.columns?.[col.name] || `Field ${col.name}`;
    telegramMsg += `${cidx + 1}. ${col.name} (${col.type})\n   → ${colDesc}\n`;
  });

  telegramMsg += `\`\`\`\n\n`;
});

markdown += `\n---\n\n`;

// Detail per table in markdown
tables.forEach((table, idx) => {
  const aiTable = aiDoc.tables?.find(t => t.name === table.name) || {};

  markdown += `## ${idx + 1}. \`${table.name}\`\n\n`;
  markdown += `### Deskripsi\n${aiTable.description || 'Dokumentasi otomatis'}\n\n`;
  markdown += `### Kolom\n\n`;
  markdown += `| No | Nama Field | Tipe Data | Deskripsi |\n`;
  markdown += `|----|------------|-----------|-----------|\n`;

  table.columns.forEach((col, cidx) => {
    const colDesc = aiTable.columns?.[col.name] || `Field ${col.name}`;
    markdown += `| ${cidx + 1} | ${col.name} | ${col.type} | ${colDesc} |\n`;
  });

  markdown += `\n<details>\n<summary>📝 SQL Definition</summary>\n\n`;
  markdown += `\`\`\`sql\n${table.definition}\n\`\`\`\n\n</details>\n\n---\n\n`;
});

telegramMsg += `✅ *Total: ${tables.length} table(s)*\n`;
telegramMsg += `📁 _File juga diupload ke Google Drive_`;

const fileName = `dokumentasi_${new Date().toISOString().slice(0,10)}_${Date.now()}.md`;

return [{
  json: {
    chatId,
    telegramMessage: telegramMsg,
    markdown,
    fileName,
    tableCount: tables.length
  }
}];
